function passwordScore(value='') {
  let score = 0;
  if (value.length >= 10) score++;
  if (/[a-z]/.test(value) && /[A-Z]/.test(value)) score++;
  if (/\d/.test(value)) score++;
  if (/[^A-Za-z0-9]/.test(value)) score++;
  if (value.length >= 14) score++;
  return Math.min(score,5);
}
function passwordSetupView() {
  const recovery = Boolean(api.session?.recovery);
  const expiresAt = state.accountSecurity?.temporary_password_expires_at;
  const expired = !recovery && state.accountSecurity?.must_change_password && expiresAt && new Date(expiresAt).getTime() < Date.now();
  if (expired) return `<main class="onboarding-shell security-onboarding"><section class="onboarding-card"><header class="onboarding-head"><span class="security-hero-icon">${icon('lock',28)}</span><span class="eyebrow">${L('أمان الحساب','ACCOUNT SECURITY')}</span><h1>${L('انتهت صلاحية كلمة المرور المؤقتة','Temporary password has expired')}</h1><p>${L('اطلب من مسؤول الحساب إصدار كلمة مرور مؤقتة جديدة، ثم حاول تسجيل الدخول مرة أخرى.','Ask your administrator to issue a new temporary password, then sign in again.')}</p></header><button class="btn btn-primary btn-block" data-action="sign-out">${L('العودة لتسجيل الدخول','Return to sign in')}</button></section></main>`;
  const profile=state.profile||{};
  return `<main class="security-setup-shell"><section class="security-setup-aside"><div class="brand"><span class="brand-mark">O</span><span>Optimum</span></div><div><span class="eyebrow">${recovery?L('استعادة كلمة المرور','PASSWORD RECOVERY'):L('تأمين أول دخول','FIRST LOGIN')}</span><h1>${recovery?L('أنشئ كلمة مرور جديدة','Create a new password'):L('أمّن حسابك قبل البدء','Secure your account before you start')}</h1><p>${recovery?L('اختر كلمة مرور قوية وغير مستخدمة في حسابات أخرى.','Choose a strong password you do not use elsewhere.'):L('هذه الخطوة إلزامية مرة واحدة فقط. لن تتمكن من دخول مساحة الشركة قبل إكمالها.','This mandatory step happens once. Your company workspace stays locked until it is complete.')}</p></div><div class="security-points"><span>${icon('shield',18)} ${L('كلمة المرور المؤقتة لا تُحفظ كنص واضح','Temporary credentials are never stored as plain text')}</span><span>${icon('check',18)} ${L('كل إجراء مهم مسجل في سجل النشاط','Important actions are recorded in the audit trail')}</span><span>${icon('lock',18)} ${L('بيانات كل شركة معزولة بالكامل','Every company is fully isolated')}</span></div></section><section class="security-setup-main"><div class="security-setup-card"><header><span class="security-step">${recovery?L('استعادة الحساب','Account recovery'):L('الخطوة 1 من 1','Step 1 of 1')}</span><h2>${recovery?L('تعيين كلمة المرور','Set your password'):L(`مرحبًا ${profile.full_name||api.user?.email?.split('@')[0]||''}`,`Welcome, ${profile.full_name||api.user?.email?.split('@')[0]||''}`)}</h2><p>${recovery?L('بعد الحفظ ستعود مباشرة إلى مساحة عملك.','After saving, you will return directly to your workspace.'):L('راجع بياناتك وأنشئ كلمة مرور خاصة بك.','Review your details and create your private password.')}</p></header><form class="form-grid" data-form="first-login" data-recovery="${recovery}">${recovery?'':`<div class="form-grid cols-2"><div class="form-row"><label>${L('الاسم الكامل','Full name')}</label><input class="input" name="full_name" autocomplete="name" value="${e(profile.full_name||'')}" required /></div><div class="form-row"><label>${L('المنطقة الزمنية','Timezone')}</label><select class="select" name="timezone">${timezoneOptions(profile.timezone||'Africa/Cairo')}</select></div><div class="form-row"><label>${L('رقم الهاتف','Phone number')}</label><input class="input" name="phone" type="tel" autocomplete="tel" value="${e(profile.phone||'')}" /></div><div class="form-row"><label>${L('واتساب','WhatsApp')}</label><input class="input" name="whatsapp" type="tel" value="${e(profile.whatsapp||'')}" /></div></div>`}<div class="password-fields"><div class="form-row"><label>${L('كلمة المرور الجديدة','New password')}</label><input class="input" name="password" type="password" autocomplete="new-password" minlength="10" required data-password-input /></div><div class="form-row"><label>${L('تأكيد كلمة المرور','Confirm password')}</label><input class="input" name="confirm_password" type="password" autocomplete="new-password" minlength="10" required /></div></div><div class="password-meter" data-password-meter><span></span><span></span><span></span><span></span><span></span></div><div class="password-helper">${icon('info',14)} <span>${L('استخدم كلمة مرور جديدة مختلفة عن كلمة المرور المؤقتة أو الحالية.','Use a new password that is different from the temporary or current password.')}</span></div><div class="password-rules"><span data-rule="length">${icon('check',13)} ${L('10 أحرف على الأقل','At least 10 characters')}</span><span data-rule="case">${icon('check',13)} ${L('حروف كبيرة وصغيرة','Upper and lower case')}</span><span data-rule="number">${icon('check',13)} ${L('رقم واحد على الأقل','At least one number')}</span><span data-rule="symbol">${icon('check',13)} ${L('رمز خاص','A special symbol')}</span></div>${recovery?'':`<label class="terms-check"><input type="checkbox" name="accept_terms" value="true" required /><span>${L('أوافق على شروط الاستخدام وسياسة الخصوصية الخاصة بمنصة Optimum.','I accept the Optimum terms of use and privacy policy.')}</span></label>`}<button class="btn btn-primary btn-lg btn-block" type="submit">${icon('shield',17)} ${recovery?L('حفظ كلمة المرور','Save password'):L('حفظ والدخول إلى مساحة العمل','Secure account and enter workspace')}</button></form><button class="btn btn-ghost btn-block" data-action="sign-out" style="margin-top:10px">${L('تسجيل الخروج','Sign out')}</button></div></section></main>`;
}
function accessPendingView() {
  return `<main class="onboarding-shell"><section class="onboarding-card"><header class="onboarding-head"><span class="brand-mark">O</span><h1>${L('لا توجد مساحة عمل مرتبطة بحسابك','No workspace is linked to your account')}</h1><p>${L('تأكد أنك تستخدم البريد الذي أنشأه مسؤول Optimum أو مسؤول شركتك، أو تواصل معه لتفعيل الوصول.','Make sure you are using the account provisioned by Optimum or your company administrator, or contact them to activate access.')}</p></header><div class="alert alert-info">${icon('mail')}<div class="alert-copy"><strong>${e(api.user?.email||'')}</strong><p>${L('لا يمكن إنشاء شركة أو حساب جديد من داخل تطبيق العملاء.','Companies and public accounts cannot be created from the client application.')}</p></div></div><button class="btn btn-secondary btn-block" data-action="sign-out" style="margin-top:10px">${e(t('signOut'))}</button></section></main>`;
}

const companyNav = [
  ['dashboard','dashboard',()=>t('dashboard')],['tasks','checkSquare',()=>L('المهام','Tasks')],['calendar','calendar',()=>L('التقويم','Calendar')],['engineering','drafting',()=>L('CAD والهندسة','CAD & Engineering')],['projects','briefcase',()=>t('projects')],['files','folder',()=>L('مساحة الملفات','Files Workspace')],['trash','trash',()=>L('سلة المحذوفات','Trash')],
  ['team','users',()=>t('team')],['organization','building',()=>L('المؤسسة','Organization')],['roles','shield',()=>t('roles')],['activity','activity',()=>t('activity')],['settings','settings',()=>t('settings')]
];
function pageTitle() {
  const names={files:L('مساحة الملفات','Files Workspace'),trash:L('سلة المحذوفات','Trash'),tasks:L('المهام','Tasks'),calendar:L('التقويم','Calendar'),engineering:L('CAD والهندسة','CAD & Engineering'),notifications:L('الإشعارات','Notifications'),organization:L('نظام المؤسسة','Organization OS')};
  return names[state.page]||t(state.page)||t('dashboard');
}
function shell(content) {
  const name=state.profile?.full_name||api.user?.email||'User'; const unread=state.notifications.filter((x)=>!x.read_at).length;
  const companySwitch=state.company?`<button class="company-switch-btn" data-action="company-switch">${state.branding?.logo_path?imageOrInitials(state.branding.logo_path,state.company.name,'company-avatar company-avatar-image'):`<span class="company-avatar">${e(initials(state.company.name))}</span>`}<span class="company-switch-copy"><strong>${e(state.company.name)}</strong><span>${e(roleLabel(state.role))}</span></span>${icon('chevronDown',16)}</button>`:'';
  return `<div class="app-shell"><aside class="sidebar ${state.sidebarOpen?'open':''}"><div class="brand">${state.branding?.logo_path?imageOrInitials(state.branding.logo_path,brandName(),'brand-logo'):'<span class="brand-mark">O</span>'}<span>${e(brandName())}</span></div><div class="company-switch">${companySwitch}</div>${state.company?`<div class="nav-section-label">${e(t('company'))}</div><nav class="nav-list">${companyNav.filter(([p])=>navAllowed(p)).map(([p,ic,label])=>`<button class="nav-link ${state.page===p?'active':''}" data-nav="${p}">${icon(ic,19)}<span>${e(label())}</span>${p==='trash'&&trashCount()?`<span class="nav-count">${trashCount()}</span>`:p==='tasks'&&taskAttentionCount()?`<span class="nav-count task-count">${taskAttentionCount()}</span>`:''}</button>`).join('')}</nav>`:''}<div class="sidebar-bottom"><div class="foundation-badge"><strong>${icon('check',15)} ${L('المؤسسة جاهزة للعمل','Organization ready')}</strong><p>${L('Site Delivery & Claim Intelligence · 6.9.0','Site Delivery & Claim Intelligence · 6.9.0')}</p></div><button class="nav-link" data-action="sign-out">${icon('logout',18)}<span>${e(t('signOut'))}</span></button></div></aside><div class="main-column"><header class="topbar"><button class="icon-btn mobile-nav" data-action="mobile-menu">${icon('menu')}</button><div class="topbar-title"><h1>${e(pageTitle())}</h1><p>${e(state.company?.name||L('لوحة مالك المنصة','Platform owner console'))}</p></div><div class="topbar-spacer"></div>${state.company&&(can('tasks.create')||can('members.invite')||can('roles.create')||can('members.manage')||can('projects.create'))?`<button class="icon-btn quick-create-trigger" data-action="quick-create" title="${L('إنشاء سريع','Quick Create')}">${icon('plus',18)}</button>`:''}${state.company&&can('search.use')?`<button class="command-trigger" data-action="command">${icon('search',17)}<span>${L('ابحث في كل شيء...','Search everything...')}</span><kbd>Ctrl K</kbd></button>`:''}${state.company&&can('notifications.view')?`<button class="icon-btn notification-button" data-action="notifications">${icon('bell')}${unread?`<span class="notification-count">${unread>99?'99+':unread}</span>`:''}</button>`:''}<button class="icon-btn" data-action="help">${icon('help')}</button><button class="icon-btn" data-action="toggle-locale">${icon('globe')}</button><button class="icon-btn" data-action="toggle-theme">${icon(currentTheme()==='dark'?'sun':'moon')}</button><button class="avatar-button" data-action="account-menu">${state.profile?.avatar_path?imageOrInitials(state.profile.avatar_path,name,'identity-avatar'):e(initials(name))}</button></header><main class="page">${content}</main></div></div>`;
}
