  return `<div class="suspension-banner">${icon('lock',20)}<div><strong>${status==='suspended'?L('مساحة العمل موقوفة مؤقتًا','Workspace is temporarily suspended'):L('انتهى اشتراك مساحة العمل','Workspace subscription has expired')}</strong><p>${L('يمكنك عرض بيانات الشركة الأساسية، لكن العمليات والملفات متوقفة حتى إعادة التفعيل.','You can view company basics, but operations and files are paused until reactivation.')}</p></div></div>`;
