function openStorageIntelligence(){const x=state.storageIntelligence||{},max=Number(x.max_storage_bytes||state.storageMetrics?.max_storage_bytes||0),used=Number(x.used_bytes||0),pct=max?usagePercent(used,max):0;openDrawer({title:L('ذكاء التخزين','Storage Intelligence'),subtitle:L('افهم أين تذهب مساحة الشركة قبل اتخاذ قرارات الحذف.','Understand where company storage goes before deleting anything.'),wide:true,body:`<section class="storage-intelligence-hero"><div><span class="eyebrow">STORAGE INTELLIGENCE</span><h2>${formatBytes(used)}</h2><p>${max?`${formatBytes(used)} / ${formatBytes(max)}`:L('بدون حد مسجل','No recorded limit')}</p></div><strong>${pct}%</strong></section>${percentBar(pct)}<div class="pdc-kpi-grid"><article>${icon('trash',17)}<strong>${formatBytes(x.trash_bytes||0)}</strong><span>${L('في السلة','In trash')}</span></article><article>${icon('repeat',17)}<strong>${formatBytes(x.old_version_bytes||0)}</strong><span>${L('إصدارات قديمة','Old versions')}</span></article><article>${icon('briefcase',17)}<strong>${asArray(x.by_project).length}</strong><span>${L('مشاريع مستخدمة','Projects')}</span></article></div><div class="section-head"><div><h3>${L('حسب المشروع','By project')}</h3></div></div><div class="storage-breakdown">${asArray(x.by_project).map(p=>`<button data-action="open-project" data-id="${p.id}"><span><strong>${e(p.code)} — ${e(p.name)}</strong></span><b>${formatBytes(p.bytes)}</b></button>`).join('')}</div><div class="section-head"><div><h3>${L('أكبر الملفات الحالية','Largest current files')}</h3></div></div><div class="storage-breakdown">${asArray(x.largest_files).map(d=>`<button data-action="navigate-entity" data-type="document" data-id="${d.id}"><span><strong>${e(d.display_name)}</strong></span><b>${formatBytes(d.size_bytes)}</b></button>`).join('')||`<p class="muted">${L('لا توجد ملفات','No files')}</p>`}</div>`});}

async function navigateToEntityLegacy68(type,id){try{const c=await api.rpc('resolve_entity_context',{p_entity_type:type,p_entity_id:id});closeOverlay();if(c.type==='project'){location.hash='#/projects';render();await openProjectDetails(c.project_id);}else if(c.type==='site'){location.hash='#/projects';render();await openSiteDetails(c.site_id);}else if(c.type==='folder'||c.type==='document'){state.selectedProjectId=c.project_id;state.selectedSiteId=c.site_id||'project';state.currentFolderId=c.folder_id||null;localStorage.setItem(filesProjectKey,state.selectedProjectId||'');localStorage.setItem(filesSiteKey,state.selectedSiteId||'project');location.hash='#/files';await loadFilesData();render();if(c.type==='document')await openDocumentDetails(c.document_id);}else if(c.type==='task'){location.hash='#/tasks';render();await workOS?.openTask(c.task_id);}else if(c.type==='engineering_drawing'){location.hash='#/engineering';render();await engineering.openDrawing(c.drawing_id);}}catch(err){formError(err);}}

function openUploadDialogLegacy68(){if(!can('files.upload')){toast('error',L('غير مسموح','Not allowed'),L('لا تملك صلاحية رفع الملفات.','You do not have permission to upload files.'));return;}if(limitReached('storage')){toast('error',L('مساحة التخزين ممتلئة','Storage limit reached'),planLimitLabel('storage'));return;}if(!currentFolder())return;state.pendingUploads=[];openDialog({title:L('رفع الملفات','Upload files'),subtitle:folderDisplay(currentFolder()),large:true,body:`<form class="form-grid" data-form="upload-files"><label class="drop-zone" for="upload-input">${icon('upload',28)}<strong>${L('اختر ملفًا أو عدة ملفات','Choose one or multiple files')}</strong><span>${L('الحد الأقصى للملف الواحد 1 GB','Maximum 1 GB per file')}</span><input id="upload-input" type="file" multiple hidden /></label><div id="upload-review"></div><div class="form-row two"><div class="form-row"><label>${L('نوع المستند','Document type')}</label><select class="select" name="document_type"><option value="general">${L('عام','General')}</option><option value="drawing">${L('رسم','Drawing')}</option><option value="report">${L('تقرير','Report')}</option><option value="contract">${L('عقد','Contract')}</option><option value="photo">${L('صورة','Photo')}</option><option value="boq">BOQ</option></select></div><div class="form-row"><label>${L('الكلمات المفتاحية — افصل بفاصلة','Tags — comma separated')}</label><input class="input" name="tags" /></div></div><div class="form-row"><label>${e(t('description'))}</label><textarea class="textarea" name="description"></textarea></div><button class="btn btn-primary" type="submit" disabled id="upload-submit">${icon('upload')} ${L('بدء الرفع','Start upload')}</button></form>`});}
function uploadReviewHtml(){if(!state.pendingUploads.length)return'';return `<div class="upload-review-list">${state.pendingUploads.map((item,i)=>{const matches=state.documents.filter((d)=>d.folder_id===state.currentFolderId&&d.state==='active'&&normalizeName(d.display_name)===normalizeName(item.file.name));const progress=state.uploadProgress[i]||{status:'ready',percent:0};const statusText=progress.status==='uploading'?`${L('جاري الرفع','Uploading')} ${progress.percent}%`:progress.status==='finalizing'?L('جاري حفظ الإصدار','Finalizing version'):progress.status==='done'?L('تم الرفع','Uploaded'):progress.status==='error'?L('فشل الرفع — يمكنك المحاولة مرة أخرى','Upload failed — you can retry'):L('جاهز للرفع','Ready');return `<div class="upload-review-row ${progress.status}"><span class="document-icon">${fileTypeIcon(item.file.type,20)}</span><div class="upload-review-main"><input class="input upload-display-name" data-index="${i}" value="${e(item.displayName)}" ${['uploading','finalizing','done'].includes(progress.status)?'disabled':''}/><small>${e(item.file.name)} · ${formatBytes(item.file.size)}</small><div class="upload-progress"><span style="width:${progress.percent||0}%"></span></div><em>${e(statusText)}${progress.error?` · ${e(progress.error)}`:''}</em></div><select class="select upload-mode" data-index="${i}" ${['uploading','finalizing','done'].includes(progress.status)?'disabled':''}><option value="new" ${item.mode==='new'?'selected':''}>${L('ملف جديد','New file')}</option>${entitlementEnabled('feature.file_versioning')?matches.map((d)=>`<option value="version:${d.id}" ${item.documentId===d.id?'selected':''}>${L('إصدار جديد من','New version of')} ${e(d.display_name)}</option>`).join(''):''}</select></div>`;}).join('')}</div>`;}
function refreshUploadReview(){const box=document.querySelector('#upload-review');if(box)box.innerHTML=uploadReviewHtml();const submit=document.querySelector('#upload-submit');if(submit)submit.disabled=state.uploadBatchRunning||!state.pendingUploads.length||state.pendingUploads.every((_,i)=>state.uploadProgress[i]?.status==='done');}
function openNewVersionDialog(id){if(!entitlementEnabled('feature.file_versioning')){toast('error',L('إصدارات الملفات غير مفعلة','File versioning is disabled'),L('فعّل الميزة للشركة من لوحة المنصة أولًا.','Enable this company feature from the platform console first.'));return;}const d=state.documents.find((x)=>x.id===id);openDialog({title:L('إضافة إصدار جديد','Add new version'),subtitle:d?.display_name||'',body:`<form class="form-grid" data-form="new-version" data-id="${id}"><div class="form-row"><label>${L('الملف','File')}</label><input class="input" name="file" type="file" required /></div><div class="form-row"><label>${L('ما الذي تغير؟','What changed?')}</label><textarea class="textarea" name="change_note"></textarea></div><button class="btn btn-primary" type="submit">${icon('upload')} ${L('رفع الإصدار','Upload version')}</button></form>`});}
async function openDocumentDetailsLegacy68(id){
  openDrawer({title:L('المستند','Document'),subtitle:L('تحميل Document 360...','Loading Document 360...'),wide:true,body:`<div class="search-loading"><span class="busy-dot"></span>${e(t('loading'))}</div>`});
  try{const x=await api.rpc('document_360',{p_document_id:id}),d=x.document,versions=asArray(x.versions),current=versions.find(v=>v.id===d.current_version_id)||versions.find(v=>v.upload_state==='ready'),versioning=entitlementEnabled('feature.file_versioning');if(!d)return;
    const existing=state.documents.findIndex(z=>z.id===d.id);if(existing>=0)state.documents[existing]={...state.documents[existing],...d};else state.documents.push(d);for(const v of versions){const i=state.versions.findIndex(z=>z.id===v.id);const row={...v,document_id:d.id,company_id:d.company_id,storage_bucket:'company-files'};if(i>=0)state.versions[i]={...state.versions[i],...row};else state.versions.push(row);}
    const history=versioning?`<div class="section-head"><div><h3>${L('سجل الإصدارات','Version history')}</h3><p>${versions.length}</p></div></div><div class="version-list">${versions.map(v=>`<div class="version-row ${v.id===d.current_version_id?'current':''}"><span class="version-number">v${v.version_number}</span><span class="version-copy"><strong>${e(v.original_filename)}</strong><small>${formatBytes(v.size_bytes)} · ${e(v.uploader_name||getProfile(v.uploaded_by).full_name)} · ${e(formatDateTime(v.finalized_at||v.created_at))}${v.change_note?`<br>${e(v.change_note)}`:''}</small></span>${statusBadge(v.upload_state)}${v.upload_state==='ready'&&can('files.download')?`<button class="icon-btn" data-action="preview-version" data-id="${v.id}">${icon('eye',15)}</button><button class="icon-btn" data-action="download-version" data-id="${v.id}">${icon('download',15)}</button>`:''}</div>`).join('')}</div>`:'';
    openDrawer({title:d.display_name,subtitle:`${e(d.document_type)} · ${e(documentControlLabel(d.control_status))}`,wide:true,body:`<section class="document360-hero"><span class="document-hero-icon">${fileTypeIcon(current?.mime_type,30)}</span><div><span class="eyebrow">DOCUMENT 360</span><h2>${e(d.display_name)}</h2><p>${e([d.system_code,d.discipline,current?.original_filename].filter(Boolean).join(' · '))}</p><div class="project360-meta"><button class="link-button" data-action="open-project" data-id="${x.project?.id}">${icon('briefcase',13)} ${e(x.project?.name||'')}</button>${x.site?`<button class="link-button" data-action="open-site" data-id="${x.site.id}">${icon('map',13)} ${e(x.site.name)}</button>`:''}<button class="link-button" data-action="navigate-entity" data-type="folder" data-id="${x.folder?.id}">${icon('folder',13)} ${e(x.folder?.name||'')}</button></div></div>${documentControlBadge(d.control_status||'working')}</section><div class="drawer-action-grid">${can('files.upload')&&versioning?`<button class="btn btn-primary" data-action="new-version" data-id="${d.id}">${icon('upload')} ${L('إصدار جديد','New version')}</button>`:''}${current&&can('files.download')?`<button class="btn btn-secondary" data-action="preview-version" data-id="${current.id}">${icon('eye')} ${L('فتح الحالي','Open current')}</button><button class="btn btn-secondary" data-action="download-version" data-id="${current.id}">${icon('download')} ${L('تنزيل','Download')}</button>`:''}</div><div class="metadata-grid"><div><span>${L('الحالة الرسمية','Control status')}</span><strong>${e(documentControlLabel(d.control_status))}</strong></div><div><span>${L('المسؤول','Owner')}</span><strong>${e(x.owner_name||'—')}</strong></div><div><span>${L('موعد المراجعة','Review due')}</span><strong>${e(d.review_due_at?formatDateTime(d.review_due_at):'—')}</strong></div><div><span>${L('آخر تعديل','Updated')}</span><strong>${e(formatDateTime(d.updated_at))}</strong></div></div>${d.description?`<div class="description-box">${e(d.description)}</div>`:''}${can('files.manage')?`<div class="document-control-actions"><span>${L('دورة المستند','Document control')}</span>${['working','in_review','approved','rejected','superseded'].map(st=>`<button class="btn btn-sm ${d.control_status===st?'btn-primary':'btn-ghost'}" data-action="set-document-control" data-id="${d.id}" data-status="${st}">${e(documentControlLabel(st))}</button>`).join('')}</div>`:''}<div class="document360-links"><section><div class="section-head"><div><h3>${L('العمل المرتبط','Linked work')}</h3><p>${asArray(x.linked_tasks).length}</p></div></div>${asArray(x.linked_tasks).map(tk=>`<button class="entity-link-row" data-action="navigate-entity" data-type="task" data-id="${tk.id}"><span>#${tk.task_number} · ${e(tk.title)}</span>${statusBadge(tk.status)}</button>`).join('')||`<p class="muted">${L('لا يوجد عمل مرتبط','No linked work')}</p>`}</section><section><div class="section-head"><div><h3>${L('الرسومات المرتبطة','Linked drawings')}</h3><p>${asArray(x.linked_drawings).length}</p></div></div>${asArray(x.linked_drawings).map(dr=>`<button class="entity-link-row" data-action="navigate-entity" data-type="engineering_drawing" data-id="${dr.id}"><span>${e(dr.drawing_no)} · ${e(dr.title)}</span><small>${e(dr.relation_type||'')}</small></button>`).join('')||`<p class="muted">${L('لا توجد رسومات مرتبطة','No linked drawings')}</p>`}</section></div>${history}<div class="document-danger-zone">${can('files.rename')?`<button class="btn btn-secondary btn-sm" data-action="rename-document" data-id="${d.id}">${icon('edit',14)} ${L('تعديل الاسم','Rename')}</button>`:''}${can('files.move')?`<button class="btn btn-secondary btn-sm" data-action="move-document" data-id="${d.id}">${icon('move',14)} ${L('نقل','Move')}</button>`:''}${can('files.archive')?`<button class="btn btn-danger-soft btn-sm" data-action="trash-document" data-id="${d.id}">${icon('trash',14)} ${L('نقل إلى السلة','Move to trash')}</button>`:''}</div>`});
  }catch(err){formError(err);}
}
function openRenameDocument(id){const d=state.documents.find((x)=>x.id===id);openDialog({title:L('تعديل اسم الملف','Rename file'),body:`<form class="form-grid" data-form="rename-document" data-id="${id}"><div class="form-row"><label>${L('الاسم الظاهر','Display name')}</label><input class="input" name="name" value="${e(d?.display_name||'')}" required /></div><button class="btn btn-primary" type="submit">${e(t('save'))}</button></form>`});}
function openMoveDocument(id){openDialog({title:L('نقل الملف','Move file'),body:`<form class="form-grid" data-form="move-document" data-id="${id}"><div class="form-row"><label>${L('المجلد الجديد','New folder')}</label><select class="select" name="folder_id" required>${folderOptions()}</select></div><button class="btn btn-primary" type="submit">${icon('move')} ${L('نقل','Move')}</button></form>`});}

function taskProject(id){return state.projects.find((x)=>x.id===id)||null;}
function taskSite(id){return state.sites.find((x)=>x.id===id)||null;}
function taskFolder(id){return state.folders.find((x)=>x.id===id)||null;}
function taskDocument(id){return state.documents.find((x)=>x.id===id)||null;}
function taskAssignees(id){return state.taskAssignments.filter((x)=>x.task_id===id);}
function taskChecklist(id){return state.taskChecklist.filter((x)=>x.task_id===id).sort((a,b)=>a.position-b.position);}
function taskComments(id){return state.taskComments.filter((x)=>x.task_id===id&&!x.deleted_at);}
function taskAttachments(id){return state.taskAttachments.filter((x)=>x.task_id===id&&x.upload_state==='ready');}
function taskEvents(id){return state.taskEvents.filter((x)=>x.task_id===id).slice(0,50);}
function taskSeries(id){return state.taskSeries.find((x)=>x.id===id)||null;}
function taskCode(task){return `TSK-${String(task.task_number||0).padStart(5,'0')}`;}
function taskMemberRole(){return state.membership?.role_id||null;}
function taskIsMine(task){const a=taskAssignees(task.id);return task.created_by===api.user?.id||task.claimed_by===api.user?.id||a.some((x)=>x.user_id===api.user?.id||x.role_id===taskMemberRole());}
function taskCanAct(task,key){return can('tasks.manage')||(can(key)&&taskIsMine(task));}
function taskAttentionCount(){return state.tasks.filter((x)=>taskIsMine(x)&&!['done','cancelled'].includes(x.status)&&(x.status==='blocked'||(x.due_at&&new Date(x.due_at)<new Date()))).length;}
function isOverdue(task){return task.due_at&&!['done','cancelled'].includes(task.status)&&new Date(task.due_at)<new Date();}
function isDueToday(task){if(!task.due_at)return false;const d=new Date(task.due_at),n=new Date();return d.getFullYear()===n.getFullYear()&&d.getMonth()===n.getMonth()&&d.getDate()===n.getDate();}
function taskStatusLabel(status){return {todo:L('مطلوبة','To do'),in_progress:L('قيد التنفيذ','In progress'),blocked:L('متوقفة','Blocked'),done:L('مكتملة','Done'),cancelled:L('ملغاة','Cancelled')}[status]||status;}
function taskPriorityLabel(priority){return {low:L('منخفضة','Low'),medium:L('متوسطة','Medium'),high:L('عالية','High'),urgent:L('عاجلة','Urgent')}[priority]||priority;}
function taskStatusBadge(status){return `<span class="task-status status-${e(status)}"><span></span>${e(taskStatusLabel(status))}</span>`;}
function taskPriorityBadge(priority){return `<span class="task-priority priority-${e(priority)}">${icon('flag',13)} ${e(taskPriorityLabel(priority))}</span>`;}
function taskContext(task){const parts=[];const p=taskProject(task.project_id),s=taskSite(task.site_id),f=taskFolder(task.folder_id),d=taskDocument(task.document_id);if(p)parts.push(p.name);if(s)parts.push(s.name);if(f)parts.push(folderDisplay(f));if(d)parts.push(d.display_name);return parts.join(' / ');}
function taskAssigneeChips(task,compact=false){const rows=taskAssignees(task.id),items=[];for(const a of rows){if(a.user_id){const p=getProfile(a.user_id);items.push(`<span class="assignee-chip" title="${e(p.full_name||'')}"><span>${e(initials(p.full_name))}</span>${compact?'':`<b>${e(p.full_name||L('مستخدم','User'))}</b>`}</span>`);}else if(a.role_id){const r=getRole(a.role_id);items.push(`<span class="assignee-chip role-chip" title="${e(roleLabel(r))}">${icon('users',13)}${compact?'':`<b>${e(roleLabel(r))}</b>`}</span>`);}}if(task.open_unassigned)items.push(`<span class="assignee-chip open-chip">${icon('hand',13)}${compact?'':`<b>${L('متاحة للاستلام','Open')}</b>`}</span>`);if(task.visibility==='private')items.push(`<span class="assignee-chip private-chip">${icon('lock',13)}${compact?'':`<b>${L('خاصة','Private')}</b>`}</span>`);return items.length?`<div class="assignee-stack">${items.join('')}</div>`:`<span class="muted-inline">${L('بدون مسؤول','Unassigned')}</span>`;}
function checklistProgress(task){const items=taskChecklist(task.id);if(!items.length)return null;const done=items.filter((x)=>x.is_completed).length;return {done,total:items.length,percent:Math.round(done/items.length*100)};}
function taskFiltered(){let rows=[...state.tasks];if(state.taskScope==='my')rows=rows.filter(taskIsMine);else if(state.taskScope==='open')rows=rows.filter((x)=>x.open_unassigned&&!x.claimed_by&&!['done','cancelled'].includes(x.status));else if(state.taskScope==='completed')rows=rows.filter((x)=>x.status==='done');else if(state.taskScope==='team'&&!can('tasks.view_all'))rows=rows.filter(taskIsMine);if(state.taskStatusFilter==='active')rows=rows.filter((x)=>!['done','cancelled'].includes(x.status));else if(state.taskStatusFilter!=='all')rows=rows.filter((x)=>x.status===state.taskStatusFilter);if(state.taskProjectFilter!=='all')rows=rows.filter((x)=>x.project_id===state.taskProjectFilter);const q=state.taskSearch.trim().toLowerCase();if(q)rows=rows.filter((x)=>`${x.title} ${x.description||''} ${taskCode(x)} ${taskContext(x)}`.toLowerCase().includes(q));return rows.sort((a,b)=>{const ao=isOverdue(a)?0:1,bo=isOverdue(b)?0:1;if(ao!==bo)return ao-bo;if(a.due_at&&b.due_at)return new Date(a.due_at)-new Date(b.due_at);if(a.due_at)return-1;if(b.due_at)return 1;return new Date(b.created_at)-new Date(a.created_at);});}
function taskCard(task){const cp=checklistProgress(task),comments=taskComments(task.id).length,attachments=taskAttachments(task.id).length,context=taskContext(task);return `<article class="work-card priority-${task.priority} ${isOverdue(task)?'overdue':''} status-border-${task.status}" data-action="open-task" data-id="${task.id}" tabindex="0"><header><div class="task-code-row"><span class="task-code">${e(taskCode(task))}</span>${taskPriorityBadge(task.priority)}</div><button class="icon-btn task-open-icon" data-action="open-task" data-id="${task.id}">${icon('chevron',15)}</button></header><h4>${e(task.title)}</h4>${context?`<p class="task-context">${icon('link',13)} ${e(context)}</p>`:''}<div class="task-card-meta">${task.due_at?`<span class="due-chip ${isOverdue(task)?'danger':isDueToday(task)?'warning':''}">${icon('calendar',13)} ${e(isDueToday(task)?L('اليوم','Today'):formatDateTime(task.due_at))}</span>`:`<span class="due-chip">${icon('calendar',13)} ${L('بدون موعد','No due date')}</span>`}${task.series_id?`<span class="recurring-chip">${icon('repeat',13)} ${L('متكررة','Recurring')}</span>`:''}</div>${cp?`<div class="mini-progress"><div><span style="width:${cp.percent}%"></span></div><small>${cp.done}/${cp.total}</small></div>`:''}<footer><div>${taskAssigneeChips(task,true)}</div><div class="task-counters">${comments?`<span>${icon('comment',13)} ${comments}</span>`:''}${attachments?`<span>${icon('paperclip',13)} ${attachments}</span>`:''}</div></footer></article>`;}
function taskListRow(task){const cp=checklistProgress(task),context=taskContext(task);return `<tr class="task-row" data-action="open-task" data-id="${task.id}"><td><div class="task-title-cell"><strong>${e(task.title)}</strong><small>${e(taskCode(task))}${context?` · ${e(context)}`:''}</small></div></td><td>${taskStatusBadge(task.status)}</td><td>${taskPriorityBadge(task.priority)}</td><td>${taskAssigneeChips(task,true)}</td><td><span class="${isOverdue(task)?'text-danger':''}">${e(task.due_at?formatDateTime(task.due_at):'—')}</span></td><td>${cp?`${cp.done}/${cp.total}`:'—'}</td></tr>`;}
function taskBoard(rows){const columns=[['todo',L('مطلوبة','To do')],['in_progress',L('قيد التنفيذ','In progress')],['blocked',L('متوقفة','Blocked')],['done',L('مكتملة','Done')]];return `<div class="kanban-board">${columns.map(([status,label])=>{const list=rows.filter((x)=>x.status===status);return `<section class="kanban-column column-${status}"><header><div><span class="status-dot"></span><strong>${e(label)}</strong></div><span class="column-count">${list.length}</span></header><div class="kanban-stack">${list.map(taskCard).join('')||`<div class="kanban-empty">${L('لا توجد مهام','No tasks')}</div>`}</div></section>`;}).join('')}</div>`;}
function taskContent(){const rows=taskFiltered();if(!rows.length)return emptyState('checkSquare',L('لا توجد مهام بهذه التصفية','No tasks match this view'),L('غيّر التصفية أو أنشئ مهمة جديدة.','Change the filters or create a new task.'),can('tasks.create')?`<button class="btn btn-primary" data-action="new-task">${icon('plus')} ${L('مهمة جديدة','New task')}</button>`:'');if(state.taskView==='list')return `<section class="card section-card task-table-card"><div class="table-wrap"><table><thead><tr><th>${L('المهمة','Task')}</th><th>${L('الحالة','Status')}</th><th>${L('الأولوية','Priority')}</th><th>${L('المسؤول','Assignee')}</th><th>${L('الموعد','Due')}</th><th>${L('التقدم','Progress')}</th></tr></thead><tbody>${rows.map(taskListRow).join('')}</tbody></table></div></section>`;return taskBoard(rows);}
function tasksPage(){if(!can('tasks.view'))return forbiddenPage();const open=state.tasks.filter((x)=>!['done','cancelled'].includes(x.status)),overdue=open.filter(isOverdue),today=open.filter(isDueToday),blocked=open.filter((x)=>x.status==='blocked');return `${pageHeader(L('إدارة العمل','Work Management'),L('اعرف المطلوب اليوم، وزّع العمل، وتابع التنفيذ بدون ضياع التفاصيل.','Know what is due, assign work, and follow execution without losing context.'),can('tasks.create')?`<button class="btn btn-primary" data-action="new-task">${icon('plus')} ${L('مهمة جديدة','New task')}</button>`:'')}<div class="grid grid-4 task-kpis"><article class="card stat-card compact"><span class="stat-icon">${icon('checkSquare')}</span><div><div class="stat-value">${open.length}</div><div class="stat-label">${L('مهام نشطة','Active tasks')}</div></div></article><article class="card stat-card compact"><span class="stat-icon warning">${icon('calendar')}</span><div><div class="stat-value">${today.length}</div><div class="stat-label">${L('مطلوبة اليوم','Due today')}</div></div></article><article class="card stat-card compact"><span class="stat-icon danger">${icon('alert')}</span><div><div class="stat-value">${overdue.length}</div><div class="stat-label">${L('متأخرة','Overdue')}</div></div></article><article class="card stat-card compact"><span class="stat-icon blocked">${icon('pause')}</span><div><div class="stat-value">${blocked.length}</div><div class="stat-label">${L('متوقفة','Blocked')}</div></div></article></div><section class="work-toolbar card"><div class="segmented task-scopes"><button class="${state.taskScope==='my'?'active':''}" data-action="task-scope" data-scope="my">${L('عملي','My work')}</button>${can('tasks.view_all')?`<button class="${state.taskScope==='team'?'active':''}" data-action="task-scope" data-scope="team">${L('الفريق','Team')}</button>`:''}<button class="${state.taskScope==='open'?'active':''}" data-action="task-scope" data-scope="open">${L('متاحة للاستلام','Open')}</button><button class="${state.taskScope==='completed'?'active':''}" data-action="task-scope" data-scope="completed">${L('المكتملة','Completed')}</button></div><div class="toolbar-grow"></div><div class="input-wrap task-search-wrap">${icon('search',15)}<input class="input" id="task-search" value="${e(state.taskSearch)}" placeholder="${L('ابحث في المهام...','Search tasks...')}" /></div><select class="select compact-select" id="task-project-filter"><option value="all">${L('كل المشاريع','All projects')}</option>${state.projects.filter((x)=>!x.archived_at).map((p)=>`<option value="${p.id}" ${state.taskProjectFilter===p.id?'selected':''}>${e(p.name)}</option>`).join('')}</select><div class="segmented view-toggle"><button class="${state.taskView==='board'?'active':''}" data-action="task-view" data-view="board">${icon('columns',16)}</button><button class="${state.taskView==='list'?'active':''}" data-action="task-view" data-view="list">${icon('list',16)}</button></div></section><div class="task-filter-row">${[['active',L('النشطة','Active')],['all',L('الكل','All')],['todo',L('مطلوبة','To do')],['in_progress',L('قيد التنفيذ','In progress')],['blocked',L('متوقفة','Blocked')],['done',L('مكتملة','Done')]].map(([k,v])=>`<button class="filter-pill ${state.taskStatusFilter===k?'active':''}" data-action="task-status-filter" data-status="${k}">${e(v)}</button>`).join('')}</div><div class="task-content-region">${taskContent()}</div>`;}
function renderTaskResultsOnly(){const region=document.querySelector('.task-content-region');if(region)region.innerHTML=taskContent();}
function workDashboardSection(){const mine=state.tasks.filter(taskIsMine).filter((x)=>!['done','cancelled'].includes(x.status)).sort((a,b)=>(a.due_at?new Date(a.due_at):Infinity)-(b.due_at?new Date(b.due_at):Infinity)).slice(0,6);const m=state.workMetrics||{};return `<section class="work-dashboard"><div class="section-head"><div><span class="eyebrow">${L('إدارة العمل','WORK MANAGEMENT')}</span><h3>${L('يوم العمل','Workday')}</h3><p>${L('المهام التي تحتاج انتباهك الآن.','Tasks that need your attention now.')}</p></div><button class="btn btn-secondary btn-sm" data-nav="tasks">${L('فتح كل المهام','Open all tasks')} ${icon('chevron',14)}</button></div><div class="work-dashboard-grid"><div class="work-summary-strip"><div><b>${m.my_todo||0}</b><span>${L('نشطة عندي','My active')}</span></div><div class="warning"><b>${m.due_today||0}</b><span>${L('اليوم','Today')}</span></div><div class="danger"><b>${m.overdue||0}</b><span>${L('متأخرة','Overdue')}</span></div><div class="blocked"><b>${m.blocked||0}</b><span>${L('متوقفة','Blocked')}</span></div><div class="success"><b>${m.completed_this_week||0}</b><span>${L('أنجزت هذا الأسبوع','Done this week')}</span></div></div><div class="my-day-list">${mine.length?mine.map((x)=>`<button class="my-day-item" data-action="open-task" data-id="${x.id}"><span class="priority-line priority-${x.priority}"></span><span><strong>${e(x.title)}</strong><small>${e(taskCode(x))} · ${e(x.due_at?(isDueToday(x)?L('اليوم','Today'):relativeTime(x.due_at)):L('بدون موعد','No due date'))}</small></span>${taskStatusBadge(x.status)}${icon('chevron',15)}</button>`).join(''):emptyState('checkSquare',L('لا توجد مهام عاجلة','No urgent work'),L('كل شيء تحت السيطرة حاليًا.','Everything is under control.'))}</div></div></section>`;}
function calendarPage(){if(!can('tasks.view'))return forbiddenPage();const y=state.calendarCursor.getFullYear(),m=state.calendarCursor.getMonth(),first=new Date(y,m,1),startDay=(first.getDay()+6)%7,days=new Date(y,m+1,0).getDate(),prevDays=new Date(y,m,0).getDate(),cells=[];for(let i=0;i<42;i++){const day=i-startDay+1;let date,current=true;if(day<1){date=new Date(y,m-1,prevDays+day);current=false;}else if(day>days){date=new Date(y,m+1,day-days);current=false;}else date=new Date(y,m,day);const iso=`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`,rows=state.tasks.filter((t)=>{const v=t.due_at||t.start_at;if(!v)return false;const d=new Date(v);return d.getFullYear()===date.getFullYear()&&d.getMonth()===date.getMonth()&&d.getDate()===date.getDate()&&!['cancelled'].includes(t.status);});const n=new Date(),today=n.getFullYear()===date.getFullYear()&&n.getMonth()===date.getMonth()&&n.getDate()===date.getDate();cells.push(`<div class="calendar-cell ${current?'':'outside'} ${today?'today':''}" data-date="${iso}"><header><span>${date.getDate()}</span>${rows.length?`<b>${rows.length}</b>`:''}</header><div class="calendar-items">${rows.slice(0,4).map((t)=>`<button class="calendar-task status-${t.status} priority-${t.priority}" data-action="open-task" data-id="${t.id}" title="${e(t.title)}"><span></span>${e(t.title)}</button>`).join('')}${rows.length>4?`<small>+${rows.length-4} ${L('أخرى','more')}</small>`:''}</div></div>`);}const month=new Intl.DateTimeFormat(i18n.locale==='ar'?'ar-EG':'en-GB',{month:'long',year:'numeric'}).format(first);return `${pageHeader(L('تقويم العمل','Work Calendar'),L('شاهد المواعيد والاستحقاقات في صورة شهرية واضحة.','See starts and due dates in a clear monthly view.'),can('tasks.create')?`<button class="btn btn-primary" data-action="new-task">${icon('plus')} ${L('مهمة جديدة','New task')}</button>`:'')}<section class="card calendar-shell"><header class="calendar-toolbar"><div class="calendar-nav"><button class="icon-btn" data-action="calendar-prev">${icon(i18n.locale==='ar'?'chevron':'chevronLeft',17)}</button><button class="btn btn-secondary btn-sm" data-action="calendar-today">${L('اليوم','Today')}</button><button class="icon-btn" data-action="calendar-next">${icon(i18n.locale==='ar'?'chevronLeft':'chevron',17)}</button></div><h3>${e(month)}</h3><div class="calendar-legend"><span class="priority-urgent"><i></i>${L('عاجلة','Urgent')}</span><span class="status-done"><i></i>${L('مكتملة','Done')}</span></div></header><div class="calendar-weekdays">${(i18n.locale==='ar'?['الاثنين','الثلاثاء','الأربعاء','الخميس','الجمعة','السبت','الأحد']:['Mon','Tue','Wed','Thu','Fri','Sat','Sun']).map((x)=>`<span>${x}</span>`).join('')}</div><div class="calendar-grid">${cells.join('')}</div></section>`;}
function memberOptions(selected=[],selfOnly=false){return state.members.filter((m)=>m.status==='active'&&(!selfOnly||m.user_id===api.user?.id)).map((m)=>{const p=getProfile(m.user_id);return `<label class="check-option"><input type="checkbox" name="assignee_user" value="${m.user_id}" ${selected.includes(m.user_id)?'checked':''}/><span class="member-mini-avatar">${e(initials(p.full_name))}</span><span><strong>${e(p.full_name||L('مستخدم','User'))}</strong><small>${e(roleLabel(getRole(m.role_id)))}</small></span></label>`;}).join('');}
function roleAssignmentOptions(selected=[]){return state.roles.filter((r)=>!['owner','admin'].includes(r.slug)).map((r)=>`<label class="check-option"><input type="checkbox" name="assignee_role" value="${r.id}" ${selected.includes(r.id)?'checked':''}/><span class="member-mini-avatar role">${icon('users',15)}</span><span><strong>${e(roleLabel(r))}</strong><small>${state.members.filter((m)=>m.status==='active'&&m.role_id===r.id).length} ${L('أعضاء','members')}</small></span></label>`).join('');}
function contextOptions(task={}){const projectId=task.project_id||'';const sites=state.sites.filter((x)=>x.project_id===projectId&&!x.archived_at),folders=state.folders.filter((x)=>x.project_id===projectId&&!x.trashed_at),documents=state.documents.filter((x)=>x.project_id===projectId&&x.state==='active');return `<div class="form-row"><label>${L('المشروع','Project')}</label><select class="select" name="project_id" id="task-project-select"><option value="">${L('بدون مشروع','No project')}</option>${state.projects.filter((x)=>!x.archived_at).map((p)=>`<option value="${p.id}" ${projectId===p.id?'selected':''}>${e(p.code)} — ${e(p.name)}</option>`).join('')}</select></div><div class="form-row"><label>${L('الموقع','Site')}</label><select class="select" name="site_id" id="task-site-select"><option value="">${L('بدون موقع','No site')}</option>${sites.map((x)=>`<option value="${x.id}" ${task.site_id===x.id?'selected':''}>${e(x.name)}</option>`).join('')}</select></div><div class="form-row"><label>${L('الفولدر المرتبط','Linked folder')}</label><select class="select" name="folder_id" id="task-folder-select"><option value="">${L('بدون فولدر','No folder')}</option>${folders.map((x)=>`<option value="${x.id}" ${task.folder_id===x.id?'selected':''}>${e(folderDisplay(x))}</option>`).join('')}</select></div><div class="form-row"><label>${L('الملف المرتبط','Linked file')}</label><select class="select" name="document_id" id="task-document-select"><option value="">${L('بدون ملف','No file')}</option>${documents.map((x)=>`<option value="${x.id}" ${task.document_id===x.id?'selected':''}>${e(x.display_name)}</option>`).join('')}</select></div>`;}
function refreshTaskContextFields(form,projectId){const site=form.querySelector('#task-site-select'),folder=form.querySelector('#task-folder-select'),doc=form.querySelector('#task-document-select');if(site)site.innerHTML=`<option value="">${L('بدون موقع','No site')}</option>`+state.sites.filter((x)=>x.project_id===projectId&&!x.archived_at).map((x)=>`<option value="${x.id}">${e(x.name)}</option>`).join('');if(folder)folder.innerHTML=`<option value="">${L('بدون فولدر','No folder')}</option>`+state.folders.filter((x)=>x.project_id===projectId&&!x.trashed_at).map((x)=>`<option value="${x.id}">${e(folderDisplay(x))}</option>`).join('');if(doc)doc.innerHTML=`<option value="">${L('بدون ملف','No file')}</option>`+state.documents.filter((x)=>x.project_id===projectId&&x.state==='active').map((x)=>`<option value="${x.id}">${e(x.display_name)}</option>`).join('');}
function openTaskDialog(task=null){if(!can('tasks.create')&&!task)return;const assignments=task?taskAssignees(task.id):[],users=assignments.map((x)=>x.user_id).filter(Boolean),roles=assignments.map((x)=>x.role_id).filter(Boolean);let mode=task?.visibility==='private'?'private':task?.open_unassigned?'open':roles.length?'roles':'users';if(!task)users.push(api.user.id);const series=task?.series_id?taskSeries(task.series_id):null;const canAssignTask=can('tasks.assign')||can('tasks.manage');const assignmentControl=canAssignTask?`<select class="select assignment-mode" name="assignment_mode"><option value="users" ${mode==='users'?'selected':''}>${L('أشخاص محددون','Specific members')}</option><option value="roles" ${mode==='roles'?'selected':''}>${L('دور أو فريق','Role / team')}</option><option value="open" ${mode==='open'?'selected':''}>${L('متاحة لأي شخص','Open for anyone')}</option><option value="private" ${mode==='private'?'selected':''}>${L('مهمة شخصية خاصة','Private personal task')}</option></select><div class="assignment-scroll"><div class="assignment-users"><small>${L('الأعضاء','Members')}</small>${memberOptions(users)}</div><div class="assignment-roles"><small>${L('الأدوار','Roles')}</small>${roleAssignmentOptions(roles)}</div></div>`:task?`<input type="hidden" name="assignment_mode" value="${mode}"><div class="assignment-readonly">${taskAssigneeChips(task)}<small>${L('تغيير المسؤول متاح للمدير فقط.','Only a manager can change assignment.')}</small></div>`:`<select class="select assignment-mode" name="assignment_mode"><option value="users">${L('مُسندة إليّ','Assigned to me')}</option><option value="private">${L('مهمة شخصية خاصة','Private personal task')}</option></select><div class="assignment-scroll"><div class="assignment-users"><small>${L('المسؤول','Assignee')}</small>${memberOptions([api.user.id],true)}</div></div>`;openDialog({title:task?L('تعديل المهمة','Edit task'):L('مهمة جديدة','New task'),subtitle:L('اجعل المطلوب واضحًا وحدد المسؤول والموعد والسياق.','Make the outcome clear, then set ownership, timing, and context.'),large:true,extraClass:'task-dialog',body:`<form class="task-form" data-form="task" ${task?`data-id="${task.id}"`:''}><section class="task-form-main"><div class="form-row"><label>${L('عنوان المهمة','Task title')}</label><input class="input input-lg" name="title" value="${e(task?.title||'')}" maxlength="240" required placeholder="${L('مثال: مراجعة مخطط الدور الأرضي','Example: Review ground-floor drawing')}" /></div><div class="form-row"><label>${L('التفاصيل والنتيجة المطلوبة','Details and expected outcome')}</label><textarea class="textarea" name="description" rows="4" placeholder="${L('اكتب كل ما يحتاجه المنفذ بدون الرجوع لمكالمة أخرى...','Write everything needed to complete the work...')}">${e(task?.description||'')}</textarea></div><div class="form-grid cols-2"><div class="form-row"><label>${L('الأولوية','Priority')}</label><select class="select" name="priority">${['low','medium','high','urgent'].map((x)=>`<option value="${x}" ${(task?.priority||'medium')===x?'selected':''}>${e(taskPriorityLabel(x))}</option>`).join('')}</select></div><div class="task-scope-note">${icon('info',15)}<span><b>${L('نطاق المهمة','Task scope')}</b><small>${L('يتحدد تلقائيًا حسب اختيار المسؤول: شركة أو خاصة.','Set automatically by the assignee choice: company or private.')}</small></span></div><div class="form-row"><label>${L('تبدأ في','Starts')}</label><input class="input" type="datetime-local" name="start_at" value="${toLocalInput(task?.start_at)}" /></div><div class="form-row"><label>${L('موعد التسليم','Due date')}</label><input class="input" type="datetime-local" name="due_at" value="${toLocalInput(task?.due_at)}" /></div></div><div class="context-panel"><h4>${icon('link',16)} ${L('ربط المهمة بسياق العمل','Link to work context')}</h4><div class="form-grid cols-2">${contextOptions(task||{})}</div></div>${!task?`<div class="form-row"><label>${L('قائمة تحقق أولية — كل سطر خطوة','Initial checklist — one step per line')}</label><textarea class="textarea" name="checklist" rows="4" placeholder="${L('مراجعة البيانات\nتحديث الملف\nإبلاغ المدير','Review data\nUpdate file\nNotify manager')}"></textarea></div>`:''}</section><aside class="task-form-side"><div class="assignment-panel" data-mode="${mode}"><h4>${L('من سينفذ المهمة؟','Who will do it?')}</h4>${assignmentControl}</div>${!task?`<div class="recurrence-panel"><h4>${icon('repeat',16)} ${L('التكرار','Recurrence')}</h4><div class="form-row"><select class="select" name="recurrence"><option value="none">${L('لا تتكرر','Does not repeat')}</option><option value="daily">${L('يوميًا','Daily')}</option><option value="weekly">${L('أسبوعيًا','Weekly')}</option><option value="monthly">${L('شهريًا','Monthly')}</option></select></div><div class="form-grid cols-2"><div class="form-row"><label>${L('كل','Every')}</label><input class="input" type="number" min="1" max="365" name="recurrence_interval" value="1" /></div><div class="form-row"><label>${L('ينتهي في','Ends')}</label><input class="input" type="date" name="recurrence_ends_at" /></div></div></div>`:series?`<div class="alert alert-info">${icon('repeat')}<div class="alert-copy"><strong>${L('مهمة متكررة','Recurring task')}</strong><p>${L('التعديل الحالي يخص هذا الظهور فقط.','This edit affects this occurrence only.')}</p></div></div>`:''}<button class="btn btn-primary btn-lg btn-block" type="submit">${icon('check')} ${task?L('حفظ التعديلات','Save changes'):L('إنشاء المهمة','Create task')}</button></aside></form>`});}
function openTaskStatusDialog(id,target='in_progress'){const task=state.tasks.find((x)=>x.id===id);if(!task)return;openDialog({title:L('تحديث حالة المهمة','Update task status'),subtitle:task.title,body:`<form class="form-grid" data-form="task-status" data-id="${id}"><div class="form-row"><label>${L('الحالة','Status')}</label><select class="select" name="status">${['todo','in_progress','blocked','done','cancelled'].map((x)=>`<option value="${x}" ${target===x?'selected':''}>${e(taskStatusLabel(x))}</option>`).join('')}</select></div><div class="form-row"><label>${L('نسبة التقدم','Progress')}</label><input class="input" type="number" min="0" max="100" name="progress" value="${task.progress||0}" /></div><div class="form-row"><label>${L('سبب التوقف','Blocker reason')}</label><textarea class="textarea" name="blocked_reason" rows="2">${e(task.blocked_reason||'')}</textarea></div><div class="form-row"><label>${L('ملاحظة الإكمال','Completion note')}</label><textarea class="textarea" name="completion_note" rows="2">${e(task.completion_note||'')}</textarea></div><button class="btn btn-primary" type="submit">${L('تحديث الحالة','Update status')}</button></form>`});}
function openAddChecklistDialog(id){openDialog({title:L('إضافة خطوة','Add checklist item'),body:`<form class="form-grid" data-form="task-checklist" data-id="${id}"><div class="form-row"><label>${L('الخطوة','Item')}</label><input class="input" name="body" maxlength="500" required autofocus /></div><button class="btn btn-primary" type="submit">${icon('plus')} ${L('إضافة','Add')}</button></form>`});}
function openTaskAttachmentDialog(id){openDialog({title:L('إرفاق ملف بالمهمة','Attach a file'),subtitle:L('الحد الأقصى 100 MB','Maximum 100 MB'),body:`<form class="form-grid" data-form="task-attachment" data-id="${id}"><label class="upload-drop compact"><input type="file" name="file" required/><span>${icon('upload',22)}</span><strong>${L('اختر ملفًا','Choose a file')}</strong></label><button class="btn btn-primary" type="submit">${icon('paperclip')} ${L('رفع المرفق','Upload attachment')}</button></form>`});}
function taskEventText(ev){const map={'task.created':L('تم إنشاء المهمة','Task created'),'task.updated':L('تم تعديل المهمة','Task updated'),'task.status_changed':L('تم تغيير الحالة','Status changed'),'task.claimed':L('تم استلام المهمة','Task claimed'),'task.comment_added':L('تمت إضافة تعليق','Comment added'),'task.checklist_changed':L('تم تحديث قائمة التحقق','Checklist updated'),'task.attachment_added':L('تمت إضافة مرفق','Attachment added'),'task.recurrence_created':L('تم إنشاء ظهور متكرر','Recurring occurrence created')};return map[ev.event_type]||ev.event_type;}
function openTaskDetails(id){const task=state.tasks.find((x)=>x.id===id);if(!task)return;state.selectedTaskId=id;const items=taskChecklist(id),comments=taskComments(id),attachments=taskAttachments(id),events=taskEvents(id),cp=checklistProgress(task),context=taskContext(task),series=task.series_id?taskSeries(task.series_id):null;openDrawer({title:task.title,subtitle:`${taskCode(task)} · ${taskStatusLabel(task.status)}`,wide:true,body:`<div class="task-detail-hero"><div class="task-detail-badges">${taskStatusBadge(task.status)}${taskPriorityBadge(task.priority)}${series?`<span class="recurring-chip">${icon('repeat',13)} ${e(series.frequency)}</span>`:''}</div><p>${e(task.description||L('لا يوجد وصف إضافي.','No additional description.'))}</p><div class="task-progress-large"><div><span style="width:${task.progress||0}%"></span></div><b>${task.progress||0}%</b></div><div class="task-action-bar">${task.open_unassigned&&can('tasks.claim')?`<button class="btn btn-primary" data-action="claim-task" data-id="${id}">${icon('hand')} ${L('استلام المهمة','Claim task')}</button>`:''}${taskCanAct(task,'tasks.complete')?`<button class="btn btn-secondary" data-action="task-status" data-id="${id}" data-status="in_progress">${icon('play')} ${L('تحديث الحالة','Update status')}</button>`:''}${taskCanAct(task,'tasks.edit')?`<button class="btn btn-secondary" data-action="edit-task" data-id="${id}">${icon('edit')} ${L('تعديل','Edit')}</button>`:''}</div></div><div class="task-detail-grid"><section><div class="detail-section"><header><h4>${icon('info',16)} ${L('تفاصيل المهمة','Task details')}</h4></header><div class="detail-facts"><div><small>${L('المسؤول','Assignee')}</small>${taskAssigneeChips(task)}</div><div><small>${L('الموعد','Due')}</small><strong class="${isOverdue(task)?'text-danger':''}">${e(task.due_at?formatDateTime(task.due_at):L('بدون موعد','No due date'))}</strong></div><div><small>${L('السياق','Context')}</small><strong>${e(context||L('عام','General'))}</strong></div><div><small>${L('أنشأها','Created by')}</small><strong>${e(getProfile(task.created_by).full_name||L('مستخدم','User'))}</strong></div></div></div><div class="detail-section"><header><h4>${icon('checkSquare',16)} ${L('قائمة التحقق','Checklist')}</h4>${taskCanAct(task,'tasks.edit')?`<button class="btn btn-ghost btn-sm" data-action="add-checklist" data-id="${id}">${icon('plus',14)} ${L('إضافة','Add')}</button>`:''}</header>${items.length?`<div class="checklist-list">${items.map((x)=>`<button class="checklist-item ${x.is_completed?'completed':''}" data-action="toggle-checklist" data-id="${x.id}" data-task-id="${id}" data-completed="${x.is_completed}" ${taskCanAct(task,'tasks.complete')?'':'disabled'}><span class="checkbox-visual">${x.is_completed?icon('check',14):''}</span><span>${e(x.body)}</span></button>`).join('')}</div>${cp?`<div class="checklist-summary"><div><span style="width:${cp.percent}%"></span></div><small>${cp.done}/${cp.total} · ${cp.percent}%</small></div>`:''}`:emptyState('checkSquare',L('لا توجد خطوات','No checklist items'),L('قسّم المهمة إلى خطوات صغيرة واضحة.','Break the task into clear, small steps.'))}</div><div class="detail-section"><header><h4>${icon('paperclip',16)} ${L('المرفقات','Attachments')}</h4>${can('tasks.attach')?`<button class="btn btn-ghost btn-sm" data-action="attach-task" data-id="${id}">${icon('plus',14)} ${L('إرفاق','Attach')}</button>`:''}</header>${attachments.length?`<div class="attachment-list">${attachments.map((a)=>`<div class="attachment-row"><span class="entity-icon">${icon('file',16)}</span><span><strong>${e(a.original_filename)}</strong><small>${formatBytes(a.size_bytes)} · ${formatDateTime(a.created_at)}</small></span><div><button class="icon-btn" data-action="preview-task-attachment" data-id="${a.id}" title="${L('فتح','Open')}">${icon('eye',15)}</button><button class="icon-btn" data-action="download-task-attachment" data-id="${a.id}" title="${L('تنزيل','Download')}">${icon('download',15)}</button></div></div>`).join('')}</div>`:emptyState('paperclip',L('لا توجد مرفقات','No attachments'),L('أرفق الملفات اللازمة لتنفيذ المهمة.','Attach files needed to complete the task.'))}</div></section><aside><div class="detail-section comments-section"><header><h4>${icon('comment',16)} ${L('التعليقات','Comments')}</h4><span class="badge">${comments.length}</span></header><div class="comments-list">${comments.length?comments.map((c)=>{const p=getProfile(c.author_id);return `<article class="comment-item"><span class="member-mini-avatar">${e(initials(p.full_name))}</span><div><header><strong>${e(p.full_name||L('مستخدم','User'))}</strong><small>${e(relativeTime(c.created_at))}</small></header><p>${e(c.body)}</p></div></article>`;}).join(''):`<p class="empty-inline">${L('ابدأ النقاش حول التنفيذ هنا.','Start the execution discussion here.')}</p>`}</div>${can('tasks.comment')?`<form class="comment-form" data-form="task-comment" data-id="${id}"><textarea class="textarea" name="body" rows="2" required placeholder="${L('اكتب تعليقًا واضحًا...','Write a clear comment...')}"></textarea><button class="btn btn-primary btn-sm" type="submit">${icon('send',14)} ${L('إرسال','Send')}</button></form>`:''}</div><div class="detail-section timeline-section"><header><h4>${icon('activity',16)} ${L('سجل المهمة','Task timeline')}</h4></header><div class="task-timeline">${events.map((ev)=>`<div class="timeline-event"><span></span><div><strong>${e(taskEventText(ev))}</strong><small>${e(getProfile(ev.actor_id).full_name||L('النظام','System'))} · ${e(formatDateTime(ev.created_at))}</small></div></div>`).join('')}</div></div></aside></div>`});}
