async function runGlobalSearch(q){const box=document.querySelector('#command-results');if(!box)return;const quick=(workOS?.commandQuickActions()||'')+(organizationOS?.commandQuickActions()||'');if(q.trim().length<2){box.innerHTML=quick+`<p class="command-hint">${L('اكتب حرفين على الأقل.','Type at least two characters.')}</p>`;return;}box.innerHTML=quick+`<div class="search-loading"><span class="busy-dot"></span>${e(t('loading'))}</div>`;try{const rows=asArray(await api.rpc('global_search',{p_company_id:state.companyId,p_query:q.trim(),p_limit:50})).filter((row)=>{const target={project:'projects',site:'projects',folder:'files',document:'files',task:'tasks',engineering_drawing:'engineering'}[row.entity_type];return !target||navAllowed(target);});const memberResults=organizationOS?.memberSearchResults(q)||'';box.innerHTML=quick+memberResults+(rows.length?`<div class="search-results">${rows.map((r)=>`<button class="search-result" data-action="open-search-result" data-type="${r.entity_type}" data-id="${r.entity_id}" data-project-id="${r.project_id||''}" data-site-id="${r.site_id||''}" data-folder-id="${r.folder_id||''}"><span class="entity-icon">${icon(r.entity_type==='document'?'file':r.entity_type==='folder'?'folder':r.entity_type==='project'?'briefcase':r.entity_type==='task'?'checkSquare':r.entity_type==='engineering_drawing'?'drafting':'map',17)}</span><span class="entity-copy"><strong>${e(r.title)}</strong><span>${e(r.subtitle||r.entity_type)}</span></span><span class="badge">${e(r.entity_type)}</span></button>`).join('')}</div>`:emptyState('search',L('لا توجد نتائج','No results'),L('جرّب كلمات أبسط أو جزءًا من اسم الملف.','Try simpler keywords or part of the file name.')));}catch(err){box.innerHTML=quick+`<div class="alert alert-danger"><div class="alert-copy"><p>${e(friendlyError(err,L('تعذر البحث الآن','Search is temporarily unavailable')))}</p></div></div>`;}}

