async function uploadReserved(file,reservation,onProgress){let objectUploaded=false;try{await api.uploadObject(reservation.storage_bucket,reservation.storage_path,file,{onProgress});objectUploaded=true;await api.rpc('finalize_document_upload',{p_version_id:reservation.version_id,p_checksum_sha256:null});}catch(err){if(objectUploaded){try{await api.deleteObject(reservation.storage_bucket,reservation.storage_path);}catch{}}try{await api.rpc('abort_document_upload',{p_version_id:reservation.version_id});}catch{}throw err;}}
