  'upload-files':{permission:'files.upload',limit:'storage'},'new-version':{permission:'files.upload',entitlement:'feature.file_versioning'},'preview-version':{permission:'files.download'},'download-version':{permission:'files.download'},'rename-document':{permission:'files.rename'},'move-document':{permission:'files.move'},'trash-document':{permission:'files.archive'},'restore-document':{permission:'files.restore'},'set-document-control':{permission:'files.manage'},
